import {
  Injectable,
  Logger,
  ServiceUnavailableException,
} from '@nestjs/common';
import { ChatGoogleGenerativeAI } from '@langchain/google-genai';
import { PromptTemplate } from '@langchain/core/prompts';
import { StructuredOutputParser } from '@langchain/core/output_parsers';
import { z } from 'zod';
import { RagService } from './rag.service';

interface ClassifyInput {
  title: string;
  description: string;
}

interface ClassifyResult {
  category: string;
  priority: string;
  confidence: number;
}

interface ConversationMessage {
  sender: string;
  message: string;
  timestamp: string;
}

interface DraftReplyInput {
  title: string;
  description: string;
  conversationHistory?: ConversationMessage[];
}

export interface DraftReplyResult {
  draft: string;
  citations: string[];
}

@Injectable()
export class AiClientService {
  private readonly logger = new Logger(AiClientService.name);
  private llm: ChatGoogleGenerativeAI;

  constructor(private readonly ragService: RagService) {
    this.llm = new ChatGoogleGenerativeAI({
      apiKey: process.env.GEMINI_API_KEY,
      model: 'gemini-flash-latest',
      temperature: 0.2,
    });
  }

  async classify(input: ClassifyInput): Promise<ClassifyResult> {
    try {
      const parser = StructuredOutputParser.fromZodSchema(
        z.object({
          category: z
            .enum(['IT', 'HR', 'Finance', 'Admin', 'Other'])
            .describe('The department category'),
          priority: z
            .enum(['Low', 'Medium', 'High'])
            .describe('The priority level of the ticket'),
          confidence: z
            .number()
            .min(0)
            .max(1)
            .describe(
              'Your confidence score between 0.0 and 1.0 for how certain you are about the category and priority classification',
            ),
        }),
      );

      const prompt = PromptTemplate.fromTemplate(`
You are a helpdesk ticket classifier. Classify the following ticket into exactly one category and priority.

Ticket Title: {title}
Ticket Description: {description}

{format_instructions}
      `);

      const chain = prompt.pipe(this.llm).pipe(parser);
      const result = await chain.invoke({
        title: input.title,
        description: input.description,
        format_instructions: parser.getFormatInstructions(),
      });

      return result;
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error('AI classify failed, using fallback', message);
      return { category: 'Other', priority: 'Medium', confidence: 0.5 };
    }
  }

  async draftReply(input: DraftReplyInput): Promise<DraftReplyResult> {
    try {
      const query = `${input.title}\n${input.description}`;
      const relevantDocs = await this.ragService.retrieveRelevantDocs(query);

      const citations: string[] = [];
      let context = '';

      if (relevantDocs.length === 0) {
        return {
          draft:
            "I don't have specific guidance for this issue in our knowledge base. A support agent will review your ticket and respond shortly.",
          citations: [],
        };
      }

      for (const doc of relevantDocs) {
        const source = doc.metadata.source || 'Unknown Source';
        if (!citations.includes(source)) {
          citations.push(source);
        }
        context += `\n[Source: ${source}]\n${doc.pageContent}\n`;
      }

      // Build conversation history section
      let conversationSection = '';
      if (input.conversationHistory && input.conversationHistory.length > 0) {
        conversationSection = `\n---\nConversation History (oldest to newest):\n`;
        for (const msg of input.conversationHistory) {
          conversationSection += `[${msg.sender} at ${msg.timestamp}]: ${msg.message}\n`;
        }
        conversationSection += `\n---\nIMPORTANT: The above conversation has already taken place. Your new draft reply MUST continue the conversation naturally. Do NOT repeat information or suggestions already given. Address any new questions or follow-ups from the employee. If the issue seems unresolved, suggest the next logical troubleshooting step.\n`;
      }

      const prompt = PromptTemplate.fromTemplate(`
You are a helpful IT support agent at a company. Use the following knowledge base articles to draft a professional reply to the employee's support ticket.

IMPORTANT RULES:
- Base your reply ONLY on the provided knowledge base articles.
- Do not make up information not present in the articles.
- Be concise, friendly, and actionable.
{conversationHistory}

Knowledge Base Articles:
{context}

---
Employee Ticket:
Title: {title}
Description: {description}

Draft Reply:
      `);

      const chain = prompt.pipe(this.llm);
      const response = await chain.invoke({
        context,
        title: input.title,
        description: input.description,
        conversationHistory: conversationSection,
      });

      return {
        draft: (response as any).content.toString().trim(),
        citations,
      };
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error('AI draft-reply failed', message);
      throw new ServiceUnavailableException(
        'AI service is currently unavailable',
      );
    }
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import * as path from 'path';
import * as fs from 'fs';
import { PrismaService } from '../prisma/prisma.service';

// We import dynamically because transformers.js is ESM/CJS hybrid and might cause issues in some setups
let pipeline: any;

@Injectable()
export class RagService implements OnModuleInit {
  private readonly logger = new Logger(RagService.name);
  private isReady = false;
  private extractor: any;

  constructor(private readonly prisma: PrismaService) {}

  async onModuleInit() {
    try {
      this.logger.log('Initializing Postgres pgvector Store...');

      // Dynamically import Xenova transformers to avoid module resolution conflicts
      const transformers = await import('@xenova/transformers');
      pipeline = transformers.pipeline;

      this.extractor = await pipeline(
        'feature-extraction',
        'Xenova/all-MiniLM-L6-v2',
        {
          quantized: true,
        },
      );

      this.isReady = true;
      this.logger.log(
        'pgvector Store successfully initialized and ready for queries.',
      );
    } catch (error) {
      this.logger.error('Failed to initialize RAG Vector Store', error);
    }
  }

  async retrieveRelevantDocs(
    query: string,
    k: number = 3,
  ): Promise<{ pageContent: string; metadata: { source: string } }[]> {
    if (!this.isReady) {
      return [];
    }

    // Embed query
    const queryOutput = await this.extractor(query, {
      pooling: 'mean',
      normalize: true,
    });
    const queryVector = Array.from(queryOutput.data);

    // Similarity search via pgvector: 1 - (embedding <=> queryVector) is cosine similarity
    const results = await this.prisma.$queryRaw<any[]>`
      SELECT id, content, source, 1 - (embedding <=> ${queryVector}::vector) as similarity
      FROM "KnowledgeChunk"
      ORDER BY embedding <=> ${queryVector}::vector
      LIMIT ${k}
    `;

    return results.map((row) => ({
      pageContent: row.content,
      metadata: { source: row.source },
    }));
  }
}

import {
  Controller,
  Post,
  Get,
  Body,
  HttpCode,
  HttpStatus,
  Res,
  Req,
  UnauthorizedException,
  UseGuards,
} from '@nestjs/common';
import type { Response, Request } from 'express';
import { AuthService } from './auth.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';
import { JwtAuthGuard } from './guards/jwt-auth.guard';

@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  private setCookies(
    res: Response,
    access_token: string,
    refresh_token: string,
  ) {
    res.cookie('access_token', access_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days (matches jwt expiration approx)
    });
    res.cookie('refresh_token', refresh_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
    });
  }

  @Post('register')
  async register(
    @Body() dto: RegisterDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.register(dto);
    this.setCookies(res, result.access_token, result.refresh_token);
    return { user: result.user };
  }

  @Post('login')
  @HttpCode(HttpStatus.OK)
  async login(
    @Body() dto: LoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.login(dto);
    this.setCookies(res, result.access_token, result.refresh_token);
    return { user: result.user };
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  async refresh(
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    const refreshToken = req.cookies['refresh_token'];
    if (!refreshToken)
      throw new UnauthorizedException('No refresh token provided');

    const result = await this.authService.refresh(refreshToken);
    this.setCookies(res, result.access_token, result.refresh_token);
    return { user: result.user };
  }

  @Get('me')
  @UseGuards(JwtAuthGuard)
  async getMe(@Req() req: any) {
    const user = await this.authService.getMe(req.user.id);
    return { user };
  }

  @Post('logout')
  @HttpCode(HttpStatus.OK)
  logout(@Res({ passthrough: true }) res: Response) {
    res.clearCookie('access_token', { path: '/' });
    res.clearCookie('refresh_token', { path: '/' });
    return { message: 'Logged out successfully' };
  }
}

import {
  Injectable,
  UnauthorizedException,
  ConflictException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { UsersService } from '../users/users.service';
import { PermissionsService } from '../rbac/permissions.service';
import { PrismaService } from '../prisma/prisma.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';

@Injectable()
export class AuthService {
  constructor(
    private readonly usersService: UsersService,
    private readonly permissionsService: PermissionsService,
    private readonly prisma: PrismaService,
    private readonly jwtService: JwtService,
  ) {}

  async register(dto: RegisterDto) {
    const existing = await this.usersService.findByEmail(dto.email);
    if (existing) throw new ConflictException('Email already in use');

    const passwordHash = await bcrypt.hash(dto.password, 12);
    const user = await this.usersService.create({
      email: dto.email,
      name: dto.name,
      passwordHash,
    });

    // Assign default role (EMPLOYEE)
    const employeeRole = await this.prisma.rbacRole.findUnique({
      where: { code: 'EMPLOYEE' },
    });
    if (employeeRole) {
      await this.prisma.userRole.create({
        data: {
          userId: user.id,
          roleId: employeeRole.id,
        },
      });
    }

    return await this.signToken(user.id, user.email, user.name);
  }

  async login(dto: LoginDto) {
    const user = await this.usersService.findByEmail(dto.email);
    if (!user) throw new UnauthorizedException('Invalid credentials');

    const valid = await bcrypt.compare(dto.password, user.passwordHash);
    if (!valid) throw new UnauthorizedException('Invalid credentials');

    if (!user.isVerified) {
      throw new UnauthorizedException('Account awaiting admin verification');
    }

    return await this.signToken(user.id, user.email, user.name);
  }

  async refresh(refreshToken: string) {
    try {
      const payload = this.jwtService.verify(refreshToken, {
        secret: process.env.JWT_REFRESH_SECRET || 'refresh-secret-change-me',
      });

      const user = await this.prisma.user.findUnique({
        where: { id: payload.sub },
      });
      if (!user || !user.hashedRefreshToken) {
        throw new UnauthorizedException('Invalid refresh token');
      }

      const valid = await bcrypt.compare(refreshToken, user.hashedRefreshToken);
      if (!valid) throw new UnauthorizedException('Invalid refresh token');

      return await this.signToken(user.id, user.email, user.name);
    } catch (e) {
      throw new UnauthorizedException('Invalid refresh token');
    }
  }

  async getMe(userId: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new UnauthorizedException('User not found');
    return this.buildUserProfile(user.id, user.email, user.name);
  }

  private async signToken(userId: string, email: string, name: string) {
    const payload = { sub: userId, email, name };

    // Generate tokens
    const access_token = this.jwtService.sign(payload);
    const refresh_token = this.jwtService.sign(payload, {
      secret: process.env.JWT_REFRESH_SECRET || 'refresh-secret-change-me',
      expiresIn: (process.env.JWT_REFRESH_EXPIRES_IN || '30d') as any,
    });

    // Hash and store refresh token
    const hashedRefreshToken = await bcrypt.hash(refresh_token, 10);
    await this.usersService.update(userId, { hashedRefreshToken });

    const user = await this.buildUserProfile(userId, email, name);

    return {
      access_token,
      refresh_token,
      user,
    };
  }

  private async buildUserProfile(userId: string, email: string, name: string) {
    // Fetch Roles Metadata
    let roles: any[] = [];
    const userRoles = await this.prisma.userRole.findMany({
      where: { userId },
      include: { role: true },
    });
    roles = userRoles.map((ur) => ({
      code: ur.role.code,
      name: ur.role.name,
      description: ur.role.description,
    }));

    // Fetch Permissions
    let permissions: string[] = [];
    if (roles.some((r) => r.code === 'ADMIN')) {
      permissions = ['*'];
    } else {
      const permSet =
        await this.permissionsService.getUserPermissionCodes(userId);
      permissions = Array.from(permSet);
    }

    return { id: userId, email, name, roles, permissions };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';

import { UsersService } from '../../users/users.service';
import { JwtUser } from '../interfaces/jwt-user.interface';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly usersService: UsersService) {
    super({
      jwtFromRequest: (req) => {
        if (req && req.cookies) {
          return req.cookies['access_token'];
        }
        return null;
      },
      ignoreExpiration: false,
      secretOrKey: process.env.JWT_SECRET ?? 'dev-secret-change-me',
    });
  }

  async validate(payload: { sub: string; email: string }): Promise<JwtUser> {
    const user = await this.usersService.findById(payload.sub);
    if (!user) throw new UnauthorizedException();
    return {
      id: user.id,
      email: user.email,
    };
  }
}

import {
  Controller,
  Post,
  UseInterceptors,
  UploadedFile,
  BadRequestException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { KnowledgeService } from './services/knowledge.service';
import { Express } from 'express';

@Controller('knowledge')
export class KnowledgeController {
  constructor(private readonly knowledgeService: KnowledgeService) {}

  @Post('upload')
  @UseInterceptors(FileInterceptor('file'))
  async uploadFile(@UploadedFile() file: Express.Multer.File) {
    if (!file) {
      throw new BadRequestException('No file provided');
    }

    // Process file asynchronously in background (do not await to avoid blocking response for large files)
    this.knowledgeService.processDocument(file).catch((err) => {
      console.error(`Failed to process document ${file.originalname}:`, err);
    });

    return {
      message: 'File upload started. Processing asynchronously.',
      filename: file.originalname,
      size: file.size,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { RecursiveCharacterTextSplitter } from '@langchain/textsplitters';

export interface Chunk {
  content: string;
  source: string;
}

@Injectable()
export class ChunkingService {
  private readonly logger = new Logger(ChunkingService.name);

  /**
   * Semantically chunks text into pieces small enough for embedding models
   * while maintaining context overlap.
   */
  async chunkText(text: string, source: string): Promise<Chunk[]> {
    try {
      const splitter = new RecursiveCharacterTextSplitter({
        chunkSize: 1000,
        chunkOverlap: 200,
      });

      const docs = await splitter.createDocuments([text]);

      return docs.map((doc) => ({
        content: doc.pageContent,
        source,
      }));
    } catch (error: any) {
      this.logger.error(`Error chunking text for source ${source}:`, error);

      throw new Error(
        `Failed to chunk document: ${error?.message || 'Unknown error'}`,
      );
    }
  }
}

import { Injectable, UnsupportedMediaTypeException } from '@nestjs/common';
import pdfParse from 'pdf-parse';

@Injectable()
export class DocumentParserService {
  /**
   * Parses the file buffer and extracts plain text based on its extension.
   * This is an implementation of the Strategy pattern for document ingestion.
   */
  async parseText(buffer: Buffer, extension: string): Promise<string> {
    switch (extension) {
      case '.pdf':
        return this.parsePdf(buffer);
      case '.txt':
      case '.md':
      case '.csv':
        return this.parseTextFile(buffer);
      default:
        throw new UnsupportedMediaTypeException(
          `File type ${extension} is not supported for knowledge base extraction.`,
        );
    }
  }

  private async parsePdf(buffer: Buffer): Promise<string> {
    try {
      const parsePdfFunc: any = pdfParse;
      const data: any = await parsePdfFunc(buffer);
      // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-member-access
      return data.text;
    } catch (error: any) {
      throw new Error(
        `Failed to parse PDF file: ${error?.message || 'Unknown error'}`,
      );
    }
  }

  private parseTextFile(buffer: Buffer): string {
    return buffer.toString('utf-8');
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { PrismaClient } from '@prisma/client';
import { pipeline } from '@xenova/transformers';
import { Chunk } from './chunking.service';

@Injectable()
export class EmbeddingService implements OnModuleInit {
  private readonly logger = new Logger(EmbeddingService.name);
  private embedder: any;
  private prisma: PrismaClient;

  constructor() {
    this.prisma = new PrismaClient();
  }

  async onModuleInit() {
    this.logger.log('Initializing local embedding model...');
    // We use a small, fast local embedding model with 384 dimensions.
    // This perfectly matches the Unsupported("vector(384)") in schema.prisma.
    try {
      this.embedder = await pipeline(
        'feature-extraction',
        'Xenova/all-MiniLM-L6-v2',
      );
      this.logger.log('Local embedding model initialized.');
    } catch (error) {
      this.logger.error('Failed to initialize local embedding model', error);
    }
  }

  async embedAndStore(chunks: Chunk[], source: string): Promise<void> {
    if (!this.embedder) {
      throw new Error('Embedding model not initialized');
    }

    this.logger.log(
      `Generating embeddings for ${chunks.length} chunks from ${source}`,
    );

    // Process chunks in small batches to avoid memory overflow
    const BATCH_SIZE = 10;

    for (let i = 0; i < chunks.length; i += BATCH_SIZE) {
      const batch = chunks.slice(i, i + BATCH_SIZE);

      // Parallel embedding generation for the batch
      const embeddingPromises = batch.map(async (chunk) => {
        // Output from Xenova pipeline is a tensor
        // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
        const output: any = await this.embedder(chunk.content, {
          pooling: 'mean',
          normalize: true,
        });
        // eslint-disable-next-line @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access
        const vector = Array.from(output.data);
        return {
          content: chunk.content,
          source: chunk.source,
          vector,
        };
      });

      const embeddedBatch = await Promise.all(embeddingPromises);

      // Save to database using Prisma raw query (because of pgvector extension)
      for (const item of embeddedBatch) {
        // pgvector requires string representation of array e.g., '[0.1, 0.2, ...]'
        const vectorString = `[${item.vector.join(',')}]`;

        await this.prisma.$executeRaw`
          INSERT INTO "KnowledgeChunk" (id, content, source, embedding)
          VALUES (
            gen_random_uuid()::text,
            ${item.content},
            ${item.source},
            ${vectorString}::vector
          )
        `;
      }
      this.logger.debug(
        `Upserted batch ${i / BATCH_SIZE + 1}/${Math.ceil(chunks.length / BATCH_SIZE)} to vector DB.`,
      );
    }

    this.logger.log(`Completed vectorization for ${source}`);
  }
}

import { NestFactory } from '@nestjs/core';
import { ValidationPipe, VersioningType } from '@nestjs/common';
import cookieParser from 'cookie-parser';
import { join } from 'path';
import * as express from 'express';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  app.use(cookieParser());

  app.setGlobalPrefix('api');
  app.enableVersioning({
    type: VersioningType.URI,
    defaultVersion: '1',
  });

  // Get raw Express instance and register static + root routes
  const server = app.getHttpAdapter().getInstance();

  // Serve uploads — registered on raw Express so it bypasses NestJS routing
  server.use(
    '/uploads',
    (req, res, next) => {
      res.header('Access-Control-Allow-Origin', '*');
      next();
    },
    express.static(join(process.cwd(), 'uploads')),
  );

  server.get('/', (_req, res) => {
    res.json({ status: 'api is running', version: '1.0.0' });
  });

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true, // strip unknown fields
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  app.enableCors({
    origin: process.env.FRONTEND_URL || 'http://localhost:5173',
    credentials: true,
  });

  const port = process.env.PORT || 3000;
  await app.listen(port);
  console.log(`QuickDesk API running on http://localhost:${port}/api/v1`);
}

void bootstrap();

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class MetricsService {
  constructor(private readonly prisma: PrismaService) {}

  async getSummary() {
    const [tickets, auditLogs, topAgents] = await Promise.all([
      this.prisma.ticket.findMany({
        select: {
          status: true,
          aiCategory: true,
          aiPriority: true,
          aiConfidence: true,
          agentCategory: true,
          agentPriority: true,
          createdAt: true,
          resolvedAt: true,
        },
      }),
      this.prisma.auditLog.findMany({
        select: { field: true },
      }),
      this.prisma.ticket.groupBy({
        by: ['resolvedById'],
        where: { resolvedById: { not: null } },
        _count: { id: true },
        orderBy: { _count: { id: 'desc' } },
        take: 5,
      }),
    ]);

    const totalTickets = tickets.length;

    // ── Status counts ──
    const openCount = tickets.filter((t) => t.status === 'open').length;
    const resolvedCount = tickets.filter((t) => t.status === 'resolved').length;
    const resolutionRate =
      totalTickets > 0 ? Math.round((resolvedCount / totalTickets) * 100) : 0;

    // ── By Category ──
    const byCategory = tickets.reduce<Record<string, number>>((acc, t) => {
      const cat = t.agentCategory ?? t.aiCategory ?? 'Other';
      acc[cat] = (acc[cat] ?? 0) + 1;
      return acc;
    }, {});

    // ── By Priority ──
    const byPriority = tickets.reduce<Record<string, number>>((acc, t) => {
      const pri = t.agentPriority ?? t.aiPriority ?? 'Low';
      acc[pri] = (acc[pri] ?? 0) + 1;
      return acc;
    }, {});

    // ── Resolution time calculations ──
    const resolvedTimes = tickets
      .filter((t) => t.status === 'resolved' && t.resolvedAt)
      .map((t) => t.resolvedAt!.getTime() - t.createdAt.getTime())
      .sort((a, b) => a - b);

    let medianResolutionMinutes: number | null = null;
    let avgResolutionMinutes: number | null = null;

    if (resolvedTimes.length > 0) {
      const mid = Math.floor(resolvedTimes.length / 2);
      const medianMs =
        resolvedTimes.length % 2 === 0
          ? (resolvedTimes[mid - 1] + resolvedTimes[mid]) / 2
          : resolvedTimes[mid];
      medianResolutionMinutes = Math.round(medianMs / 60000);

      const avgMs =
        resolvedTimes.reduce((sum, t) => sum + t, 0) / resolvedTimes.length;
      avgResolutionMinutes = Math.round(avgMs / 60000);
    }

    // ── Override rates ──
    const categoryOverrides = auditLogs.filter(
      (l) => l.field === 'category',
    ).length;
    const priorityOverrides = auditLogs.filter(
      (l) => l.field === 'priority',
    ).length;
    const categoryOverrideRate =
      totalTickets > 0
        ? Math.round((categoryOverrides / totalTickets) * 100)
        : 0;
    const priorityOverrideRate =
      totalTickets > 0
        ? Math.round((priorityOverrides / totalTickets) * 100)
        : 0;

    // ── AI Confidence analytics ──
    const confidenceValues = tickets
      .map((t) => t.aiConfidence)
      .filter((c): c is number => c !== null && c !== undefined);

    const aiConfidence = {
      average:
        confidenceValues.length > 0
          ? Math.round(
              (confidenceValues.reduce((s, v) => s + v, 0) /
                confidenceValues.length) *
                100,
            ) / 100
          : null,
      min: confidenceValues.length > 0 ? Math.min(...confidenceValues) : null,
      max: confidenceValues.length > 0 ? Math.max(...confidenceValues) : null,
      total: confidenceValues.length,
      distribution: this.buildConfidenceDistribution(confidenceValues),
    };

    // ── Tickets by day (last 30 days) ──
    const ticketsByDay = this.buildTicketsByDay(tickets);

    // ── Top resolving agents ──
    const agentIds = topAgents
      .filter((a) => a.resolvedById)
      .map((a) => a.resolvedById as string);

    let agentMap: Record<string, string> = {};
    if (agentIds.length > 0) {
      const agents = await this.prisma.user.findMany({
        where: { id: { in: agentIds } },
        select: { id: true, name: true },
      });
      agentMap = agents.reduce(
        (acc, a) => {
          acc[a.id] = a.name;
          return acc;
        },
        {} as Record<string, string>,
      );
    }

    const topResolvingAgents = topAgents
      .filter((a) => a.resolvedById)
      .map((a) => ({
        agentId: a.resolvedById,
        name: agentMap[a.resolvedById as string] || 'Unknown',
        resolved: a._count.id,
      }));

    return {
      totalTickets,
      openCount,
      resolvedCount,
      resolutionRate,
      medianResolutionMinutes,
      avgResolutionMinutes,
      byCategory,
      byPriority,
      categoryOverrideRate,
      priorityOverrideRate,
      aiConfidence,
      ticketsByDay,
      topResolvingAgents,
    };
  }

  private buildConfidenceDistribution(values: number[]) {
    const buckets = [
      { label: '0-20%', min: 0, max: 0.2, count: 0 },
      { label: '20-40%', min: 0.2, max: 0.4, count: 0 },
      { label: '40-60%', min: 0.4, max: 0.6, count: 0 },
      { label: '60-80%', min: 0.6, max: 0.8, count: 0 },
      { label: '80-100%', min: 0.8, max: 1.01, count: 0 },
    ];

    for (const val of values) {
      for (const bucket of buckets) {
        if (val >= bucket.min && val < bucket.max) {
          bucket.count++;
          break;
        }
      }
    }

    return buckets.map((b) => ({ label: b.label, count: b.count }));
  }

  private buildTicketsByDay(
    tickets: { createdAt: Date }[],
  ): { date: string; count: number }[] {
    const now = new Date();
    const days: { date: string; count: number }[] = [];

    for (let i = 29; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().slice(0, 10);
      days.push({ date: dateStr, count: 0 });
    }

    for (const ticket of tickets) {
      const dateStr = ticket.createdAt.toISOString().slice(0, 10);
      const entry = days.find((d) => d.date === dateStr);
      if (entry) {
        entry.count++;
      }
    }

    return days;
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import * as nodemailer from 'nodemailer';

@Injectable()
export class EmailService implements OnModuleInit {
  private readonly logger = new Logger(EmailService.name);
  private transporter: nodemailer.Transporter;
  private fromAddress = 'quickdesk-support@gmail.com';

  async onModuleInit() {
    try {
      if (process.env.ENABLE_EMAIL === 'false') {
        this.logger.warn(
          'Email service is explicitly disabled via ENABLE_EMAIL=false. Skipping Google SMTP transporter initialization.',
        );
        return;
      }

      // Default to Google SMTP/Gmail configurations
      const host = process.env.SMTP_HOST || 'smtp.gmail.com';
      const port = process.env.SMTP_PORT ? Number(process.env.SMTP_PORT) : 587;
      const user = process.env.SMTP_USER;
      const pass = process.env.SMTP_PASS; // 16-character Google App Passkey

      if (user && pass) {
        this.logger.log(
          `Initializing free Google SMTP Transporter (${host}:${port}) for user: ${user}...`,
        );
        this.transporter = nodemailer.createTransport({
          host,
          port,
          secure: port === 465, // true for 465 SSL, false for STARTTLS
          auth: { user, pass },
        });
        this.fromAddress = process.env.SMTP_FROM || user;
      } else {
        this.logger.error(
          '❌ Google SMTP / Gmail credentials missing! Please configure SMTP_USER (your Gmail address) and SMTP_PASS (your 16-character Google App Passkey) inside your .env file to enable email dispatch.',
        );
      }
    } catch (error) {
      this.logger.error(
        'Failed to initialize Google SMTP Nodemailer transporter',
        error,
      );
    }
  }

  async sendMail(to: string, subject: string, htmlContent: string) {
    if (!this.transporter) {
      this.logger.warn(
        'Google SMTP transporter not initialized (missing .env credentials), skipping mail dispatch.',
      );
      return;
    }

    try {
      await this.transporter.sendMail({
        from: `"QuickDesk Support" <${this.fromAddress}>`,
        to,
        subject,
        html: htmlContent,
      });

      this.logger.log(
        `✉️ Email dispatched successfully via Google SMTP: Subject="${subject}" To="${to}"`,
      );
    } catch (error) {
      this.logger.error(`Failed to send email to ${to} via Google SMTP`, error);
    }
  }
}

