import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
  UseInterceptors,
  UploadedFiles,
  BadRequestException,
} from '@nestjs/common';
import { FilesInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { extname } from 'path';
import { v4 as uuidv4 } from 'uuid';
import { TicketsService } from './tickets.service';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { RolesGuard } from '../auth/guards/roles.guard';
import { Roles } from '../auth/decorators/roles.decorator';
import { CurrentUser } from '../auth/decorators/current-user.decorator';
import type { JwtUser } from '../auth/interfaces/jwt-user.interface';
import { CreateTicketDto } from './dto/create-ticket.dto';
import { OverrideTicketDto } from './dto/override-ticket.dto';
import { ReplyTicketDto } from './dto/reply-ticket.dto';
import { TicketFilterDto } from './dto/ticket-filter.dto';
import { TicketRateLimitGuard } from './guards/ticket-rate-limit.guard';

@Controller('tickets')
@UseGuards(JwtAuthGuard, RolesGuard)
export class TicketsController {
  constructor(private readonly ticketsService: TicketsService) {}

  // Employee: submit a ticket
  @Post()
  @Roles('EMPLOYEE')
  @UseGuards(TicketRateLimitGuard)
  @UseInterceptors(
    FilesInterceptor('screenshots', 5, {
      storage: diskStorage({
        destination: './uploads',
        filename: (req, file, cb) => {
          const uniqueSuffix = uuidv4() + extname(file.originalname);
          cb(null, uniqueSuffix);
        },
      }),
      limits: {
        fileSize: 5 * 1024 * 1024, // 5MB
      },
      fileFilter: (req, file, cb) => {
        if (!file.mimetype.match(/\/(jpg|jpeg|png|gif)$/)) {
          return cb(
            new BadRequestException('Only image files are allowed!'),
            false,
          );
        }
        cb(null, true);
      },
    }),
  )
  create(
    @Body() dto: CreateTicketDto,
    @CurrentUser() user: JwtUser,
    @UploadedFiles() files: Express.Multer.File[],
  ) {
    const filenames = files?.map((f) => f.filename) || [];
    return this.ticketsService.create(dto, user.id, filenames);
  }

  // Employee: view own tickets
  @Get('mine')
  @Roles('EMPLOYEE')
  findMine(@Query() filters: TicketFilterDto, @CurrentUser() user: JwtUser) {
    return this.ticketsService.findMine(user.id, filters);
  }

  // Agent: view all tickets with filters
  @Get()
  @Roles('AGENT')
  findAll(@Query() filters: TicketFilterDto) {
    return this.ticketsService.findAll(filters);
  }

  // Agent or Employee: get ticket detail
  @Get(':id')
  @Roles('AGENT', 'EMPLOYEE')
  findOne(@Param('id') id: string) {
    return this.ticketsService.findOne(id);
  }

  // Agent: get AI draft reply for a ticket
  @Get(':id/draft')
  @Roles('AGENT')
  getDraft(@Param('id') id: string) {
    return this.ticketsService.getDraftReply(id);
  }

  // Agent: override AI-suggested category/priority
  @Patch(':id/override')
  @Roles('AGENT')
  override(
    @Param('id') id: string,
    @Body() dto: OverrideTicketDto,
    @CurrentUser() user: JwtUser,
  ) {
    return this.ticketsService.override(id, dto, user.id);
  }

  // Agent or Employee: send reply in the thread
  @Post(':id/reply')
  @Roles('AGENT', 'EMPLOYEE')
  reply(
    @Param('id') id: string,
    @Body() dto: ReplyTicketDto,
    @CurrentUser() user: JwtUser,
  ) {
    return this.ticketsService.reply(id, dto, user.id);
  }

  // Employee: Resolve the ticket
  @Patch(':id/resolve')
  @Roles('EMPLOYEE', 'AGENT')
  resolve(@Param('id') id: string, @CurrentUser() user: JwtUser) {
    return this.ticketsService.resolveTicket(id, user.id);
  }

  // Employee: Update own ticket (only open tickets)
  @Patch(':id')
  @Roles('EMPLOYEE')
  update(
    @Param('id') id: string,
    @Body() dto: CreateTicketDto,
    @CurrentUser() user: JwtUser,
  ) {
    return this.ticketsService.updateTicket(id, dto, user.id);
  }

  // Employee: Delete own ticket (soft delete - close the ticket)
  @Delete(':id')
  @Roles('EMPLOYEE')
  delete(@Param('id') id: string, @CurrentUser() user: JwtUser) {
    return this.ticketsService.deleteTicket(id, user.id);
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import {
  AiClientService,
  type DraftReplyResult,
} from '../ai-client/ai-client.service';
import { AuditService } from '../audit/audit.service';
import { AppEventEmitter } from '../events/events.service';
import { CreateTicketDto } from './dto/create-ticket.dto';
import { OverrideTicketDto } from './dto/override-ticket.dto';
import { ReplyTicketDto } from './dto/reply-ticket.dto';
import { Prisma } from '@prisma/client';
import { TicketFilterDto } from './dto/ticket-filter.dto';
import { TicketsGateway } from '../sockets/tickets.gateway';

@Injectable()
export class TicketsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly aiClient: AiClientService,
    private readonly auditService: AuditService,
    private readonly eventEmitter: AppEventEmitter,
    private readonly gateway: TicketsGateway,
  ) {}

  async create(
    dto: CreateTicketDto,
    employeeId: string,
    screenshots: string[] = [],
  ) {
    // Call AI service for classification
    const classification = await this.aiClient.classify({
      title: dto.title,
      description: dto.description,
    });

    const ticket = await this.prisma.ticket.create({
      data: {
        title: dto.title,
        description: dto.description,
        attachmentFilename: dto.attachmentFilename ?? null,
        screenshots,
        employeeId,
        aiCategory: classification.category,
        aiPriority: classification.priority,
        aiConfidence: classification.confidence,
        status: 'open',
      },
      include: { employee: { select: { id: true, name: true, email: true } } },
    });

    // Emit asynchronous event for triaging notifications (Socket.IO + Email)
    this.eventEmitter.emit('ticket.created', ticket);

    return ticket;
  }

  async findMine(employeeId: string, filters: TicketFilterDto = {}) {
    const where: Prisma.TicketWhereInput = { employeeId };

    if (filters.status) {
      where.status = filters.status as Prisma.EnumTicketStatusFilter['equals'];
    }
    if (filters.category) where.agentCategory = filters.category;
    if (filters.priority) where.agentPriority = filters.priority;
    if (filters.search) {
      where.title = { contains: filters.search, mode: 'insensitive' };
    }
    if (filters.date) {
      const startDate = new Date(filters.date);
      startDate.setUTCHours(0, 0, 0, 0);
      const endDate = new Date(filters.date);
      endDate.setUTCHours(23, 59, 59, 999);
      where.createdAt = {
        gte: startDate,
        lte: endDate,
      };
    }

    const page = Number(filters.page) || 1;
    const limit = Number(filters.limit) || 10;
    const skip = (page - 1) * limit;

    const [data, total] = await Promise.all([
      this.prisma.ticket.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip,
        take: limit,
        include: {
          employee: { select: { id: true, name: true, email: true } },
        },
      }),
      this.prisma.ticket.count({ where }),
    ]);

    return {
      data,
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit) || 1,
    };
  }

  async findAll(filters: TicketFilterDto) {
    const where: Prisma.TicketWhereInput = {};

    if (filters.status) {
      where.status = filters.status as Prisma.EnumTicketStatusFilter['equals'];
    }
    if (filters.category) where.agentCategory = filters.category;
    if (filters.priority) where.agentPriority = filters.priority;
    if (filters.search) {
      where.title = { contains: filters.search, mode: 'insensitive' };
    }
    if (filters.date) {
      const startDate = new Date(filters.date);
      startDate.setUTCHours(0, 0, 0, 0);
      const endDate = new Date(filters.date);
      endDate.setUTCHours(23, 59, 59, 999);
      where.createdAt = {
        gte: startDate,
        lte: endDate,
      };
    }

    const page = Number(filters.page) || 1;
    const limit = Number(filters.limit) || 10;
    const skip = (page - 1) * limit;

    const [data, total] = await Promise.all([
      this.prisma.ticket.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip,
        take: limit,
        include: {
          employee: { select: { id: true, name: true, email: true } },
        },
      }),
      this.prisma.ticket.count({ where }),
    ]);

    return {
      data,
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit) || 1,
    };
  }

  async findOne(id: string) {
    const ticket = await this.prisma.ticket.findUnique({
      where: { id },
      include: {
        employee: { select: { id: true, name: true, email: true } },
        auditLogs: {
          include: { agent: { select: { id: true, name: true, email: true } } },
          orderBy: { changedAt: 'desc' },
        },
        replies: {
          include: { user: { select: { id: true, name: true, email: true } } },
          orderBy: { createdAt: 'asc' },
        },
        resolvedBy: { select: { id: true, name: true, email: true } },
      },
    });
    if (!ticket) throw new NotFoundException('Ticket not found');
    return ticket;
  }

  async getDraftReply(id: string): Promise<DraftReplyResult> {
    const ticket = await this.findOne(id);

    // Build conversation history from existing replies
    const conversationHistory = (ticket.replies || []).map((reply: any) => ({
      sender: reply.user?.name || 'Unknown',
      message: reply.message,
      timestamp: new Date(reply.createdAt).toISOString(),
    }));

    const result = await this.aiClient.draftReply({
      title: ticket.title,
      description: ticket.description,
      conversationHistory,
    });

    // Store the AI draft on the ticket
    await this.prisma.ticket.update({
      where: { id },
      data: { aiDraft: result.draft, citations: result.citations },
    });

    return result;
  }

  async override(id: string, dto: OverrideTicketDto, agentId: string) {
    const ticket = await this.findOne(id);

    const updates: Prisma.TicketUpdateInput = {};
    const auditEntries: Promise<unknown>[] = [];

    if (dto.category !== undefined && dto.category !== ticket.agentCategory) {
      const from = ticket.agentCategory ?? ticket.aiCategory ?? '';
      updates.agentCategory = dto.category;
      auditEntries.push(
        this.auditService.log({
          ticketId: id,
          agentId,
          field: 'category',
          from,
          to: dto.category,
        }),
      );
    }

    if (dto.priority !== undefined && dto.priority !== ticket.agentPriority) {
      const from = ticket.agentPriority ?? ticket.aiPriority ?? '';
      updates.agentPriority = dto.priority;
      auditEntries.push(
        this.auditService.log({
          ticketId: id,
          agentId,
          field: 'priority',
          from,
          to: dto.priority,
        }),
      );
    }

    await Promise.all(auditEntries);
    return this.prisma.ticket.update({ where: { id }, data: updates });
  }

  async reply(id: string, dto: ReplyTicketDto, userId: string) {
    const ticket = await this.findOne(id);
    if (ticket.status === 'resolved') {
      throw new ForbiddenException('Ticket is already resolved');
    }

    // Determine if user is agent or employee based on logic in controller,
    // but here we just create a reply
    const reply = await this.prisma.ticketReply.create({
      data: {
        ticketId: id,
        userId: userId,
        message: dto.reply,
      },
      include: {
        user: { select: { id: true, name: true, email: true } },
      },
    });

    // Update status to in_progress if it's the first reply and the ticket is still open
    if (ticket.status === 'open') {
      await this.prisma.ticket.update({
        where: { id },
        data: { status: 'in_progress' },
      });
    }

    // Broadcast via WebSockets
    this.gateway.broadcastTicketReply(id, reply);

    return reply;
  }

  async resolveTicket(id: string, userId: string) {
    const ticket = await this.findOne(id);
    if (ticket.status === 'resolved') {
      throw new ForbiddenException('Ticket is already resolved');
    }

    const updated = await this.prisma.ticket.update({
      where: { id },
      data: {
        status: 'resolved',
        resolvedAt: new Date(),
        resolvedById: userId,
      },
      include: { employee: { select: { id: true, name: true, email: true } } },
    });

    this.eventEmitter.emit('ticket.resolved', updated);
    return updated;
  }

  async updateTicket(id: string, dto: CreateTicketDto, employeeId: string) {
    const ticket = await this.findOne(id);

    // Only allow the ticket creator to update
    if (ticket.employeeId !== employeeId) {
      throw new ForbiddenException('You can only update your own tickets');
    }

    // Don't allow updating resolved tickets
    if (ticket.status === 'resolved') {
      throw new ForbiddenException('Cannot update a resolved ticket');
    }

    // Re-classify with new content
    const classification = await this.aiClient.classify({
      title: dto.title,
      description: dto.description,
    });

    const updated = await this.prisma.ticket.update({
      where: { id },
      data: {
        title: dto.title,
        description: dto.description,
        aiCategory: classification.category,
        aiPriority: classification.priority,
        aiConfidence: classification.confidence,
        // Reset agent's custom category/priority when employee updates
        agentCategory: null,
        agentPriority: null,
      },
      include: { employee: { select: { id: true, name: true, email: true } } },
    });

    this.eventEmitter.emit('ticket.updated', updated);
    return updated;
  }

  async deleteTicket(id: string, employeeId: string) {
    const ticket = await this.findOne(id);

    // Only allow the ticket creator to delete
    if (ticket.employeeId !== employeeId) {
      throw new ForbiddenException('You can only delete your own tickets');
    }

    // Don't allow deleting in_progress or resolved tickets
    if (ticket.status !== 'open') {
      throw new ForbiddenException(
        'Can only delete open tickets. Close the ticket first.',
      );
    }

    // Soft delete by setting status to closed
    const deleted = await this.prisma.ticket.update({
      where: { id },
      data: {
        status: 'closed',
        closedAt: new Date(),
        closedReason: 'deleted_by_employee',
      },
    });

    this.eventEmitter.emit('ticket.deleted', deleted);
    return deleted;
  }
}

import {
  Injectable,
  ConflictException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import * as bcrypt from 'bcrypt';

interface CreateUserInput {
  email: string;
  name: string;
  passwordHash: string;
}

@Injectable()
export class UsersService {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: CreateUserInput) {
    return this.prisma.user.create({ data });
  }

  async createWithPassword(
    email: string,
    password: string,
    name?: string,
    isVerified?: boolean,
  ) {
    // Check if user exists
    const existing = await this.findByEmail(email);
    if (existing) {
      throw new ConflictException('Email already in use');
    }

    // Hash password
    const passwordHash = await bcrypt.hash(password, 12);

    return this.prisma.user.create({
      data: {
        email,
        name: name || email.split('@')[0],
        passwordHash,
        isVerified: isVerified ?? true, // Auto-verify when created by admin unless explicitly false
      },
      include: {
        userRoles: {
          include: {
            role: {
              select: {
                id: true,
                name: true,
                code: true,
              },
            },
          },
        },
      },
    });
  }

  async findByEmail(email: string) {
    return this.prisma.user.findUnique({ where: { email } });
  }

  async findById(id: string) {
    return this.prisma.user.findUnique({
      where: { id },
      include: {
        userRoles: {
          include: {
            role: {
              select: {
                id: true,
                name: true,
                code: true,
              },
            },
          },
        },
      },
    });
  }

  async findAll(page: number = 1, limit: number = 10) {
    const skip = (page - 1) * limit;
    const [data, count] = await Promise.all([
      this.prisma.user.findMany({
        skip,
        take: limit,
        include: {
          userRoles: {
            include: {
              role: {
                select: {
                  id: true,
                  name: true,
                  code: true,
                },
              },
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      }),
      this.prisma.user.count(),
    ]);

    return {
      data,
      count,
      totalPages: Math.ceil(count / limit),
      currentPage: page,
    };
  }

  async update(id: string, data: any) {
    return this.prisma.user.update({
      where: { id },
      data,
      include: {
        userRoles: {
          include: {
            role: {
              select: {
                id: true,
                name: true,
                code: true,
              },
            },
          },
        },
      },
    });
  }

  async assignRoles(userId: string, roleIds: string[], grantedBy?: string) {
    // Verify user exists
    const user = await this.findById(userId);
    if (!user) {
      throw new NotFoundException('User not found');
    }

    // Verify all roles exist
    const roles = await this.prisma.rbacRole.findMany({
      where: { id: { in: roleIds } },
    });
    if (roles.length !== roleIds.length) {
      throw new NotFoundException('One or more roles not found');
    }

    // Sync roles (delete all existing, then add new ones)
    await this.prisma.$transaction([
      this.prisma.userRole.deleteMany({ where: { userId } }),
      this.prisma.userRole.createMany({
        data: roleIds.map((roleId) => ({
          userId,
          roleId,
          grantedBy,
        })),
        skipDuplicates: true,
      }),
    ]);

    return this.findById(userId);
  }

  async toggleVerification(userId: string, isVerified: boolean) {
    const user = await this.findById(userId);
    if (!user) throw new NotFoundException('User not found');

    return this.prisma.user.update({
      where: { id: userId },
      data: { isVerified },
      select: {
        id: true,
        email: true,
        name: true,
        isVerified: true,
      },
    });
  }
}
